recipes.code:
{
  "inputs": [
    {
      "id": "private-key",
      "type": "promptString",
      "description": "Optional trading key — without it the server is READ-ONLY (scan/vet/info only). Signs locally; never leaves your machine.",
      "password": true
    }
  ],
  "servers": {
    "zxoar": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "zxoar-mcp@0.2.2"
      ],
      "env": {
        "PRIVATE_KEY": "${input:private-key}",
        "MAX_ETH_PER_TX": "<max-eth-per-tx>",
        "MAX_ETH_PER_SESSION": "<max-eth-per-session>",
        "MAX_TX_PER_MINUTE": "<max-tx-per-minute>",
        "RPC_URL": "<rpc-url>"
      }
    }
  }
}
